INSERT INTO system_configs (config_key, config_value, description) VALUES
('user_agreement', '# 用户协议\n\n**更新日期：2026年6月9日**\n**生效日期：2026年6月9日**\n\n欢迎您使用「找零工」平台（以下简称"本平台"）。请您在使用本平台前仔细阅读并充分理解本协议的全部内容。一旦您注册、登录或使用本平台，即视为您已阅读并同意本协议的全部条款。\n\n## 一、协议的范围\n\n1.1 本协议是您与「找零工」平台运营方（以下简称"我们"）之间关于您使用本平台服务所订立的协议。\n\n1.2 本平台包括但不限于「找零工」微信小程序及相关移动应用程序。\n\n1.3 本协议内容包括协议正文、本平台已经发布或将来可能发布的各类规则。所有规则为本协议不可分割的组成部分，与协议正文具有同等法律效力。\n\n## 二、账户注册与管理\n\n2.1 **注册条件**：您确认在注册时您已年满16周岁，并具有完全民事行为能力。未满16周岁的用户需在监护人的陪同下阅读本协议，并在监护人同意后使用本平台。\n\n2.2 **注册方式**：您可以通过微信一键登录或手机号验证码登录方式注册并使用本平台。注册成功后，您将获得本平台账户。\n\n2.3 **手机号绑定**：通过微信授权登录时，系统将获取您的微信绑定手机号并用于账户关联。手机号一经绑定不可自行修改，如需变更请联系客服。\n\n2.4 **账户安全**：您应妥善保管您的账户信息及密码安全。因您个人原因导致的账户安全问题，由您自行承担全部责任。\n\n2.5 **账户使用**：您应对您账户下的所有活动和事件承担法律责任。如发现任何未经授权使用您账户的情况，请立即通知我们。\n\n## 三、平台服务\n\n3.1 **服务内容**：本平台为零工用工提供信息匹配服务，包括但不限于岗位浏览、报名应聘、排班管理、打卡考勤、收入查询、提现等功能。\n\n3.2 **服务对象**：\n- **工人端**：为求职者提供零工岗位信息、在线报名、考勤打卡、收入管理等服务。\n- **企业端**：为企业提供岗位发布、报名审核、排班管理、考勤管理、结算管理等服务。\n\n3.3 **服务变更**：我们有权随时对本平台的服务内容进行变更、暂停或终止，恕不另行通知。\n\n3.4 **服务费用**：本平台目前为免费使用。如未来推出付费服务，我们将提前通知您并征得您的同意。\n\n## 四、用户行为规范\n\n4.1 您在使用本平台时，应遵守中华人民共和国相关法律法规及本协议的规定。\n\n4.2 您不得利用本平台从事以下行为：\n- 发布虚假、有害、违法的信息；\n- 侵犯他人合法权益，包括但不限于知识产权、隐私权等；\n- 干扰本平台正常运行或破坏本平台服务器及网络设施；\n- 利用本平台进行任何形式的欺诈活动；\n- 其他违反法律法规或损害公共利益的行为。\n\n4.3 如您违反上述规定，我们有权采取包括但不限于警告、限制功能、暂停或终止账户等措施，并保留追究法律责任的权利。\n\n## 五、岗位信息与报名\n\n5.1 本平台发布的岗位信息由企业用户发布，我们不对岗位信息的真实性、准确性和完整性承担责任。建议您在应聘前核实岗位信息。\n\n5.2 您通过本平台报名岗位后，企业有权根据其用人需求决定是否录用。报名成功不代表已获得用工确认，具体用工安排以企业通知为准。\n\n5.3 您确认报名的岗位均为您自愿选择，您应自行评估岗位的风险和适合度。\n\n## 六、考勤与薪资\n\n6.1 **打卡考勤**：您应按照排班要求在指定时间和地点进行打卡考勤。打卡数据将作为薪资结算的依据。\n\n6.2 **GPS定位**：为验证打卡位置真实性，打卡时系统将获取您的地理位置信息。您在打卡时需授权位置权限。\n\n6.3 **薪资结算**：您的薪资按照与企业约定的标准和方式计算。具体薪资以企业确认的结算金额为准。\n\n6.4 **收入提现**：您可将平台收入提现至微信零钱或绑定的银行卡。提现申请提交后，我们将在1-3个工作日内处理。\n\n6.5 **税务合规**：您理解并同意，您的收入可能涉及个人所得税申报义务，您应自行了解并遵守相关税务规定。\n\n## 七、知识产权\n\n7.1 本平台的所有内容，包括但不限于文字、图片、音频、视频、软件、程序、版面设计等，均受中华人民共和国知识产权法律法规的保护。\n\n7.2 未经我们书面许可，您不得以任何形式复制、修改、传播、发布或使用本平台的任何内容。\n\n## 八、免责声明\n\n8.1 本平台仅提供信息匹配服务，不对企业与工人之间的劳动关系或劳务关系承担法律责任。\n\n8.2 因不可抗力（包括但不限于自然灾害、政策变化、网络故障等）导致的服务中断或数据丢失，我们不承担责任。\n\n8.3 您通过本平台获取的岗位信息、薪资待遇等，我们不作任何明示或暗示的保证。\n\n## 九、协议的修改与终止\n\n9.1 我们有权根据法律法规变化及业务需要修改本协议。修改后的协议将在本平台公布，继续使用本平台即视为同意修改后的协议。\n\n9.2 您有权随时停止使用本平台。如您注销账户或停止使用本平台，我们将根据适用法律处理您的个人信息。\n\n## 十、争议解决\n\n10.1 本协议的解释、履行及争议解决均适用中华人民共和国法律。\n\n10.2 如双方就本协议内容或其执行发生任何争议，双方应友好协商解决；协商不成的，任何一方均可向有管辖权的人民法院提起诉讼。\n\n## 十一、联系我们\n\n如您对本协议有任何疑问、意见或建议，请通过以下方式联系我们：\n\n- 客服邮箱：support@zhaolingong.com\n- 客服电话：400-XXX-XXXX\n\n---\n\n*本协议最终解释权归「找零工」平台运营方所有。*', '用户协议内容，支持Markdown格式')
INSERT INTO system_configs (config_key, config_value, description) VALUES
('privacy_policy', '# 隐私政策\n\n**更新日期：2026年6月9日**\n**生效日期：2026年6月9日**\n\n「找零工」平台（以下简称"我们"）深知个人信息对您的重要性，我们将按照法律法规的规定，保护您的个人信息及隐私安全。我们制定本《隐私政策》并特别提示：希望您在使用本平台及相关服务前仔细阅读并理解本隐私政策，以便做出适当的选择。\n\n## 一、我们如何收集和使用您的个人信息\n\n我们仅会出于以下目的，收集和使用您的个人信息：\n\n### 1.1 账户注册与登录\n\n| 信息类型 | 收集目的 | 使用场景 |\n|---------|---------|----------|\n| 微信OpenID | 账户标识与登录验证 | 微信一键登录 |\n| 手机号码 | 账户绑定与身份验证 | 注册、登录、找回账户 |\n| 微信昵称、头像 | 展示用户基本信息 | 个人主页展示 |\n\n### 1.2 岗位匹配与报名\n\n| 信息类型 | 收集目的 | 使用场景 |\n|---------|---------|----------|\n| 姓名 | 岗位报名与企业核实 | 报名应聘 |\n| 工作经历 | 岗位匹配推荐 | 简历展示 |\n\n### 1.3 考勤打卡\n\n| 信息类型 | 收集目的 | 使用场景 |\n|---------|---------|----------|\n| GPS位置信息 | 验证打卡位置真实性 | 打卡签到/签退 |\n| 打卡时间 | 考勤记录与薪资结算 | 考勤管理 |\n\n### 1.4 薪资提现\n\n| 信息类型 | 收集目的 | 使用场景 |\n|---------|---------|----------|\n| 微信零钱账户 | 提现至微信 | 微信提现 |\n| 银行卡号、开户行 | 提现至银行卡 | 银行卡提现 |\n| 身份证信息 | 实名认证与合规 | 实名认证 |\n\n### 1.5 消息通知\n\n| 信息类型 | 收集目的 | 使用场景 |\n|---------|---------|----------|\n| 微信订阅消息 | 发送业务通知 | 排班提醒、审核结果 |\n\n### 1.6 安全保障\n\n| 信息类型 | 收集目的 | 使用场景 |\n|---------|---------|----------|\n| 设备信息 | 防范安全风险 | 风控检测 |\n| 操作日志 | 服务优化与问题排查 | 系统运维 |\n\n## 二、我们如何存储您的个人信息\n\n2.1 **存储地点**：我们在中国境内运营中收集和产生的个人信息，存储在中国境内。\n\n2.2 **存储期限**：我们仅在为实现目的所必需的最短时间内保留您的个人信息。在您使用本平台服务期间，我们将持续存储您的个人信息。当您注销账户后，我们将在合理期限内删除或匿名化处理您的个人信息，法律法规另有规定的除外。\n\n2.3 **安全措施**：我们采用符合业界标准的安全防护措施来保护您的个人信息，包括但不限于数据加密、访问控制、安全审计等技术手段，防止您的个人信息遭到未经授权的访问、公开披露、使用、修改、损坏或丢失。\n\n## 三、我们如何共享、转让、公开披露您的个人信息\n\n### 3.1 共享\n\n我们不会与任何公司、组织和个人共享您的个人信息，但以下情况除外：\n\n- **企业用户**：当您报名应聘岗位时，您的报名信息（姓名、联系方式等）将共享给对应的企业用户，以便企业进行报名审核和用工管理。\n- **授权同意**：经过您的明确同意后，我们可能与第三方共享您的信息。\n- **法律法规**：根据法律法规、诉讼或政府主管部门的强制性要求。\n\n### 3.2 转让\n\n我们不会将您的个人信息转让给任何公司、组织和个人，但以下情况除外：\n- 获得您的明确同意后；\n- 在涉及合并、收购或破产清算时，如涉及个人信息转让，我们会要求新的持有方继续受本政策的约束。\n\n### 3.3 公开披露\n\n我们仅会在以下情况下，公开披露您的个人信息：\n- 获得您明确同意后；\n- 基于法律法规、法律程序、诉讼或政府主管部门的强制性要求。\n\n## 四、我们如何使用第三方服务\n\n4.1 本平台使用微信开放平台提供的登录、支付等服务。这些服务会收集您的相关信息，请参阅微信开放平台的隐私政策。\n\n4.2 我们会对第三方服务进行严格的数据安全要求，确保其按照本政策及适用法律法规处理您的个人信息。\n\n## 五、您对个人信息的权利\n\n按照中国相关法律法规，您对自己的个人信息享有以下权利：\n\n5.1 **查阅权**：您有权查阅您的个人信息，法律法规规定的例外情况除外。\n\n5.2 **更正权**：当您发现我们处理的关于您的个人信息有错误时，您有权要求我们做出更正。\n\n5.3 **删除权**：在以下情形中，您可以向我们提出删除个人信息的请求：\n- 处理目的已实现或个人信息对于处理目的而言不再必要；\n- 我们停止提供产品或服务；\n- 您撤回同意；\n- 我们违反法律法规或与您的约定处理个人信息。\n\n5.4 **注销权**：您有权注销您的账户。您注销账户后，我们将停止为您提供产品或服务，并依据适用法律处理您的个人信息。\n\n5.5 **撤回同意**：您有权撤回您此前给予的同意。撤回同意后，我们将不再处理相应的个人信息，但不影响撤回前基于您的同意已进行的处理。\n\n## 六、未成年人保护\n\n6.1 本平台非常重视对未成年人个人信息的保护。如果您是未满18周岁的未成年人，请在法定监护人的陪同下阅读本隐私政策，并在征得法定监护人同意后使用本平台。\n\n6.2 对于经法定监护人同意而收集的未成年人个人信息，我们仅在法律法规允许、监护人明确同意或保护未成年人所必要的情况下使用或公开披露。\n\n6.3 如果我们发现在未获得法定监护人同意的情况下收集了未成年人的个人信息，我们将尽快删除相关信息。\n\n## 七、隐私政策的修订\n\n7.1 我们可能适时修订本隐私政策的条款，该等修订构成本隐私政策的一部分。如该等修订造成您在本隐私政策下权利的实质减少，我们将在修订生效前通过在主页上显著位置提示或向您发送通知等方式通知您。\n\n7.2 在该种情况下，若您继续使用我们的服务，即表示同意受经修订的本隐私政策的约束。\n\n## 八、联系我们\n\n如您对本隐私政策有任何疑问、意见或建议，请通过以下方式联系我们：\n\n- 隐私保护邮箱：privacy@zhaolingong.com\n- 客服电话：400-XXX-XXXX\n\n我们将在15个工作日内回复您的请求。\n\n---\n\n*本隐私政策最终解释权归「找零工」平台运营方所有。*', '隐私政策内容，支持Markdown格式')
